#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception

# Installs FileCheck and llvm-symbolizer, exactly the LLVM version llvm-tools.json pins, from
# conda-forge's llvmdev package. CI runs it in every row that runs lit tests, and it runs the same
# way locally:
#
#   .github/ci/install-llvm-tools.sh .forge/ci/llvm-tools
#
# conda-forge is the one source with both tools at a pinned point release on Linux, macOS and
# Windows: LLVM's release archives leave FileCheck out, and apt.llvm.org and Homebrew cannot pin a
# point release. The packages are a downstream build of LLVM (conda-forge's patches, linked to its
# own libLLVM), so the script checks that both tools still report the pinned version.
#
# micromamba, one static binary pinned by sha256, installs the packages that llvm-tools/<subdir>.txt
# lists. Those lockfiles pin every package by URL and hash, so nothing is solved at install time.
# Downloads go to .forge/ci/conda-pkgs, which is what CI caches. To change the LLVM version, edit
# llvm-tools.json and regenerate the lockfiles, which needs network access but no conda:
#
#   .github/ci/install-llvm-tools.sh --lock
set -euo pipefail

if [ $# -ne 1 ]; then
    echo "usage: $0 PREFIX | --lock" >&2
    exit 2
fi
here=$(cd "$(dirname "$0")" && pwd)
root=$(cd "$here/../.." && pwd)
config=$here/llvm-tools.json
llvm=$(jq -r .llvm "$config")
micromamba_version=$(jq -r .micromamba.version "$config")

suffix=
case "$(uname -s)" in
    MINGW* | MSYS* | CYGWIN*)
        # Git Bash. micromamba is a native program, so it gets D:/a/... paths, and Windows will not
        # run a file without the .exe suffix.
        root=$(cygpath -m "$root")
        suffix=.exe
        ;;
esac

# The conda subdir of the machine: the runner's, or else uname's, so that this also works locally.
host_subdir() {
    case "${RUNNER_OS:+$RUNNER_OS-$RUNNER_ARCH}" in
        Linux-X64) echo linux-64; return ;;
        macOS-ARM64) echo osx-arm64; return ;;
        Windows-X64) echo win-64; return ;;
    esac
    case "$(uname -s)-$(uname -m)" in
        Linux-x86_64) echo linux-64 ;;
        Darwin-arm64) echo osx-arm64 ;;
        MINGW*-x86_64 | MSYS*-x86_64 | CYGWIN*-x86_64) echo win-64 ;;
        *)
            echo "error: no conda-forge LLVM tools are pinned for $(uname -s) $(uname -m)" >&2
            exit 1
            ;;
    esac
}

sha256_of() {
    if command -v sha256sum >/dev/null; then
        sha256sum "$1" | cut -d' ' -f1
    else
        shasum -a 256 "$1" | cut -d' ' -f1
    fi
}

packages=$root/.forge/ci/conda-pkgs
mkdir -p "$packages"
subdir=$(host_subdir)
micromamba=$packages/micromamba$suffix
expected=$(jq -r --arg subdir "$subdir" '.micromamba.sha256[$subdir]' "$config")
if [ ! -f "$micromamba" ] || [ "$(sha256_of "$micromamba")" != "$expected" ]; then
    url=$(jq -r .micromamba.url "$config" | sed -e "s/{version}/$micromamba_version/g" -e "s/{subdir}/$subdir/g")
    echo "downloading $url"
    curl -fsSL --retry 3 -o "$micromamba.part" "$url"
    mv "$micromamba.part" "$micromamba"
    actual=$(sha256_of "$micromamba")
    if [ "$actual" != "$expected" ]; then
        echo "error: $micromamba has sha256 $actual, but llvm-tools.json pins $expected" >&2
        rm -f "$micromamba"
        exit 1
    fi
fi
chmod +x "$micromamba"
export MAMBA_ROOT_PREFIX=$root/.forge/ci/conda-root
export CONDA_PKGS_DIRS=$packages
# Nothing from the machine's own conda setup may change what is installed.
export MAMBA_NO_RC=true

if [ "$1" = --lock ]; then
    # The virtual packages stand for the oldest system conda-forge's builds support, so the solve
    # picks the same packages on every host. The macOS one is below what the runners have, so a
    # build that needs a newer macOS than the runners is never picked. glibc is ignored without a
    # Linux kernel version, so a solve for Linux on another host needs both.
    export CONDA_OVERRIDE_LINUX=5.15 CONDA_OVERRIDE_GLIBC=2.17 CONDA_OVERRIDE_OSX=15.0
    export CONDA_OVERRIDE_WIN=0
    for target in linux-64 osx-arm64 win-64; do
        lockfile=$here/llvm-tools/$target.txt
        # A dry run still wants a prefix; nothing is created in it.
        solution=$("$micromamba" create --dry-run --json --yes --prefix "$packages/dry-run" \
            --platform "$target" \
            -c conda-forge --override-channels "llvmdev=$llvm")
        {
            echo "# Generated by .github/ci/install-llvm-tools.sh --lock; do not edit by hand."
            echo "@EXPLICIT"
            jq -r '.actions.LINK | sort_by(.name)[] | "\(.url)#sha256:\(.sha256)"' <<< "$solution"
        } > "$lockfile"
        echo "wrote $lockfile"
    done
    exit 0
fi

prefix=$1
case "$prefix" in
    /* | [A-Za-z]:*) ;;
    *) prefix=$PWD/$prefix ;;
esac
case "$(uname -s)" in
    MINGW* | MSYS* | CYGWIN*) prefix=$(cygpath -m "$prefix") ;;
esac

# A rerun starts clean, so a stale prefix cannot hide a changed lockfile. Only a conda prefix is
# removed, so a mistyped PREFIX cannot delete anything else.
if [ -d "$prefix/conda-meta" ]; then
    rm -rf "${prefix:?}"
elif [ -e "$prefix" ]; then
    echo "error: $prefix exists and is not a conda prefix; remove it or choose another" >&2
    exit 1
fi
"$micromamba" create --yes --prefix "$prefix" --file "$here/llvm-tools/$subdir.txt"
# micromamba keeps each package extracted beside its archive, about six times the archives' size.
# CI caches this directory, so only the archives stay; micromamba extracts them again in seconds.
find "$packages" -name '*.conda' | while read -r archive; do
    rm -rf "${archive%.conda}"
done

if [ -n "$suffix" ]; then
    # conda puts the DLLs the tools load (zstd, zlib) in Library/bin, where Windows looks beside
    # the executable; FileCheck sits in Library/libexec/llvm and would not find them.
    cp "$prefix/Library/libexec/llvm/FileCheck.exe" "$prefix/Library/bin/FileCheck.exe"
    filecheck=$prefix/Library/bin/FileCheck.exe
    symbolizer=$prefix/Library/bin/llvm-symbolizer.exe
else
    filecheck=$prefix/libexec/llvm/FileCheck
    symbolizer=$prefix/bin/llvm-symbolizer
fi
for tool in "$filecheck" "$symbolizer"; do
    report=$("$tool" --version)
    echo "$report"
    case "$report" in
        *"LLVM version $llvm"*) ;;
        *)
            echo "error: $tool is not LLVM $llvm, which llvm-tools.json pins" >&2
            exit 1
            ;;
    esac
done
echo "FileCheck: $filecheck"
echo "llvm-symbolizer: $symbolizer"
